/** Lay out text (upper-cased) on one line: { polylines, width } in font units, baseline y=0. */
export function layout(text) {
  const polylines = [];
  let cursor = 0;
  for (const ch of text.toUpperCase()) {
    const glyph = GLYPHS[ch];
    if (!glyph) {
      cursor += SPACE_ADVANCE;
      continue;
    }
    for (const line of glyph) polylines.push(line.map(([x, y]) => [x + cursor, y]));
    cursor += ADVANCE;
  }
  const width = polylines.length ? Math.max(0, cursor - (ADVANCE - GLYPH_WIDTH)) : cursor;
  return { polylines, width };
}
